const body=$json.body??$json;
const transcript=String(body.transcript??'').trim();
if(!transcript) throw new Error('transcript is required');
if(transcript.length>200000) throw new Error('transcript exceeds 200,000 character starter limit');
const lines=transcript.split(/\r?\n/).map(v=>v.trim()).filter(Boolean);
const taskPrefixes=['todo:','action:','task:'];
const tasks=[];
for(const line of lines){
  const lower=line.toLowerCase();
  const prefix=taskPrefixes.find(p=>lower.startsWith(p));
  if(prefix){
    const text=line.slice(prefix.length).trim();
    if(text) tasks.push({text,status:'OPEN'});
  }
}
const summary=lines.filter(line=>!taskPrefixes.some(p=>line.toLowerCase().startsWith(p))).join(' ').slice(0,1000);
return [{json:{meetingId:body.meetingId??null,summary,taskCount:tasks.length,tasks:tasks.slice(0,50),humanReviewRecommended:true,source:'provided-transcript'}}];
